const segment = $input.first().json;
const cohort = $input.all().map(i => i.json);
const segmentId = segment.id || segment.segmentId;
if (!segmentId) {
  throw new Error('Missing segment ID');
}
if (!segment.ruleDefinition && !segment.rules) {
  throw new Error('Missing rule definition for segment ' + segmentId);
}
// Create WorkflowRun via backend API
let workflowRunId = '';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: ($env.CRM_API_BASE_URL || 'http://localhost:3000/api/v1') + '/segments/' + segmentId + '/workflow-runs',
    headers: { 'x-n8n-api-key': $env.N8N_API_KEY || '', 'Content-Type': 'application/json' },
    body: {},
    json: true
  });
  workflowRunId = resp.workflowRunId || '';
} catch (e) {
  // If create fails, proceed without ID; backend will auto-create during callback
  workflowRunId = '';
}
return [{
  json: {
    segmentId,
    segmentName: segment.name,
    ruleDefinition: segment.ruleDefinition || segment.rules,
    isActive: segment.isActive,
    cohortSize: cohort.length,
    cohort: cohort,
    workflowRunId: workflowRunId,
    validatedAt: new Date().toISOString()
  }
}];

const resp = $input.first().json;
const stats = {
  status: resp.status || 'UNKNOWN',
  total: resp.total ?? null,
  processed: resp.processed ?? null,
  matched: resp.matched ?? null,
  message: resp.message || '',
  source: 'backend_rule_engine',
  retrievedAt: new Date().toISOString()
};
if (stats.total === null || stats.processed === null || stats.matched === null) {
  throw new Error('Missing required statistics from backend response');
}
return [{ json: stats }];

const stats = $input.first().json;
return [{
  json: {
    segmentId: $('5. Validate Evaluation Request').first().json.segmentId,
    segmentName: $('5. Validate Evaluation Request').first().json.segmentName,
    status: stats.status,
    total: stats.total,
    processed: stats.processed,
    matched: stats.matched,
    unmatched: stats.total - stats.matched,
    matchRate: stats.total > 0 ? (stats.matched / stats.total * 100).toFixed(2) + '%' : '0%',
    message: stats.message
  }
}];

const input = $('8. Normalize Statistics').first().json;
const aiResponse = $input.first().json;
let rawText = '';
if (typeof aiResponse === 'string') rawText = aiResponse;
else if (aiResponse && aiResponse.text) rawText = aiResponse.text;
else if (aiResponse && aiResponse.content) rawText = aiResponse.content;
else rawText = JSON.stringify(aiResponse);
// Strip markdown code fences
rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
let insights = [];
try {
  const parsed = JSON.parse(rawText);
  insights = Array.isArray(parsed) ? parsed : (parsed.insights || []);
} catch (e) {
  insights = [];
}
const validInsights = insights.filter(ins => {
  if (!ins || typeof ins !== 'object') return false;
  if (typeof ins.insight !== 'string' || !ins.insight) return false;
  if (typeof ins.evidence !== 'string' || !ins.evidence) return false;
  if (typeof ins.confidence !== 'number') return false;
  return true;
});
return [{
  json: {
    segmentId: input.segmentId,
    segmentName: input.segmentName,
    total: input.total,
    processed: input.processed,
    matched: input.matched,
    unmatched: input.unmatched,
    matchRate: input.matchRate,
    aiInsights: validInsights,
    rejectedInsights: insights.length - validInsights.length,
    validatedAt: new Date().toISOString()
  }
}];
